DO $$
DECLARE
  rec RECORD;
  cur_status     VARCHAR(20);
  cur_refundable DECIMAL(10,2);
BEGIN
  FOR rec IN SELECT * FROM refund_requests ORDER BY request_id LOOP
    SELECT status, refundable_amount
      INTO cur_status, cur_refundable
      FROM refund_state
     WHERE order_line_id = rec.order_line_id;

    IF rec.request_type = 1 AND cur_status = 'none' THEN
      UPDATE refund_state
         SET status = 'pending'
       WHERE order_line_id = rec.order_line_id;

    ELSIF rec.request_type = 2
       AND cur_status = 'pending'
       AND cur_refundable >= rec.requested_amount THEN
      UPDATE refund_state
         SET status = 'approved',
             refundable_amount = refundable_amount - rec.requested_amount
       WHERE order_line_id = rec.order_line_id;

    ELSIF rec.request_type = 3 AND cur_status = 'pending' THEN
      UPDATE refund_state
         SET status = 'none'
       WHERE order_line_id = rec.order_line_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM refund_state ORDER BY order_line_id;
